<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import MeetingLibraryView from './MeetingLibraryView.vue';import {useMeetingLibrary,type LibraryRow} from './useMeetingLibrary';import {uuid} from '../../shared/api/minutes-wire';
const app=useApplication(),route=useRoute(),router=useRouter(),actor=()=>app.session.current.value?.actor.enterpriseId??null,library=useMeetingLibrary({meetings:app.meetings,publications:app.publications,library:app.meetingLibrary},actor),profile=ref<{displayName:string;department:string|null}|null>(null),source=ref<LibraryRow|null>(null),sourceError=ref<string|null>(null),notice=ref<string|null>(null),noticeDialog=ref<HTMLDialogElement>();let epoch=0,request:AbortController|null=null;
const libraryId=computed(()=>typeof route.params.id==='string'?route.params.id:null),demo=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1',profileName=computed(()=>profile.value?.displayName||actor()||'尚未登录');
const allRows=computed(()=>{const entries=new Map(library.rows.value.map(row=>[row.meeting.id,row]));if(source.value)entries.set(source.value.meeting.id,source.value);return [...entries.values()];}),visible=computed(()=>allRows.value.filter(row=>!libraryId.value||row.context.libraryId===libraryId.value)),selected=computed(()=>visible.value[0]?.context??null),sourceInLibrary=computed(()=>source.value&&source.value.context.libraryId===libraryId.value?source.value:null);
const groups=computed(()=>{const entries=new Map<string,LibraryRow[]>();for(const row of allRows.value){const key=JSON.stringify([row.context.providerId,row.context.storeInstanceId,row.context.libraryId]);const group=entries.get(key)??[];group.push(row);entries.set(key,group);}return [...entries.values()].map(rows=>({key:JSON.stringify([rows[0]!.context.providerId,rows[0]!.context.storeInstanceId,rows[0]!.context.libraryId]),context:rows[0]!.context,rows}));});
async function refresh(){const who=actor(),turn=++epoch;request?.abort();request=new AbortController();const controller=request;source.value=null;sourceError.value=null;profile.value=null;if(!who){library.invalidate();return;}
 void app.options.people(who,null,controller.signal).then(value=>{if(epoch===turn&&who===actor()&&!controller.signal.aborted)profile.value=value.items.find(person=>person.stableId===who)??null;}).catch(()=>{});
 const sourceId=typeof route.query.meeting==='string'?route.query.meeting:null;
 await library.refresh();if(epoch!==turn||who!==actor()||controller.signal.aborted||!sourceId)return;
 if(!uuid(sourceId)){sourceError.value='来源会议地址无效。';return;}
 try{const pub=(await app.publications.current(sourceId,controller.signal)).publication;if(!pub||pub.documentViewAvailability!=='READY')throw new Error('来源会议当前没有可读取的正式成果。');const context=await app.meetingLibrary.context(sourceId,pub.publicationId,controller.signal);const info=await app.info.saved(sourceId,controller.signal);if(epoch===turn&&who===actor()&&!controller.signal.aborted){const found=allRows.value.find(row=>row.meeting.id===sourceId);source.value=Object.freeze({meeting:found?.meeting??{id:sourceId,name:info.name},context});}}
 catch(cause){if(epoch===turn&&who===actor()&&!controller.signal.aborted){source.value=null;sourceError.value=cause instanceof Error?cause.message:'来源会议暂不可读取。';}}
}
function open(row:LibraryRow){void router.push(`/meeting/${row.meeting.id}/read`);}function home(){void router.push('/meetings');}function show(message:string){notice.value=message;noticeDialog.value?.showModal();}
const stopIdentity=watch(actor,()=>{epoch++;request?.abort();source.value=null;profile.value=null;library.invalidate();void refresh();},{immediate:true,flush:'sync'}),stopRoute=watch(()=>[route.params.id,route.query.meeting],()=>{void refresh();});onUnmounted(()=>{epoch++;request?.abort();stopIdentity();stopRoute();library.dispose();});
</script>
<template><div class="layout"><div class="main"><header class="topbar"><nav class="topbar-heading"><RouterLink to="/meetings" class="topbar-home"><Icon name="list"/> 我的会议</RouterLink><span class="topbar-crumb">/ 会议知识库</span></nav><div class="topbar-right"><RouterLink to="/feedback" class="btn sm ghost"><Icon name="message" :size="15"/> 我的语料反馈</RouterLink><button class="btn sm ghost" @click="show('从知识库条目打开当前有权查看的已发布会议；正式文档每次打开都会重新检查权限。')"><Icon name="guide" :size="15"/> 演示引导</button><button class="btn sm ghost" @click="refresh"><Icon name="reset" :size="15"/> 重新读取</button><details class="library-profile"><summary class="role-chip" aria-label="当前用户"><div class="avatar o">{{Array.from(profileName)[0]}}</div><div><div class="rc-name">{{profileName}}</div><div class="rc-role">会议负责人 · {{profile?.department??'--'}}</div></div></summary><div class="library-menu"><RouterLink to="/meeting-library" class="btn sm ghost">会议知识库</RouterLink><a class="btn sm ghost" href="/auth/cas/logout">退出登录</a></div></details></div></header><main class="content" :aria-busy="library.loading.value">
 <div v-if="sourceError||library.error.value" class="banner error" role="alert">{{sourceError??library.error.value}}</div><div v-for="issue in library.issues.value" :key="issue" class="banner warn" role="status">{{issue}}</div>
 <template v-if="!libraryId"><div class="page-head"><div><div class="page-title">会议知识库</div><div class="page-desc">查看当前账号可读取的已发布会议成果</div></div></div><div class="card card-p"><div v-for="group in groups" :key="group.key" class="file-item"><div style="flex:1;min-width:0"><RouterLink class="m19-name" :to="'/meeting-library/'+encodeURIComponent(group.context.libraryId)">{{group.context.libraryName}}</RouterLink><div class="small muted mt8">已读取 {{group.rows.length}} 份当前可访问的会议纪要</div></div></div><div v-if="!groups.length" class="empty">{{library.loading.value?'正在读取已发布会议…':'暂无有权查看的会议纪要'}}</div></div></template>
 <MeetingLibraryView v-else :library="selected" :rows="visible" :source="sourceInLibrary" :loading="library.loading.value" :unavailable="!library.hasMore.value" :demo="demo" @home="home" @back="sourceInLibrary&&open(sourceInLibrary)" @open="open"/>
 <div v-if="library.hasMore.value||library.error.value" class="pager"><button class="btn" :disabled="library.loading.value" @click="library.more">{{library.error.value?'重试当前页':'继续读取会议成果'}}</button></div><p v-if="library.hasMore.value" class="small muted mt8">尚有会议成果未读取，当前仅展示已核实的条目。</p>
 <div v-if="demo" class="demo-note">当前页面数据均为产品演示用模拟数据，不代表招商基金真实业务信息。<br>当前原型为纯前端交互演示，不连接招商基金真实业务系统。当前原型仅展示会议负责人的相关功能。</div>
 </main><dialog ref="noticeDialog" class="notice-dialog"><form method="dialog"><p>{{notice}}</p><button class="btn primary">知道了</button></form></dialog></div></div></template>
<style scoped>.library-profile{position:relative}.library-profile>summary{cursor:pointer;list-style:none}.library-profile>summary::-webkit-details-marker{display:none}.library-menu{position:absolute;right:0;top:calc(100% + 4px);z-index:45;display:flex;flex-direction:column;align-items:stretch;min-width:150px;padding:8px;background:white;border:1px solid var(--border);border-radius:8px;box-shadow:var(--shadow-lg)}</style>
